      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications and standards do you support?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS supports documented electronics recycling and data handling programs. Depending on the project, documentation may reference NIST 800-88, HIPAA safeguards, California e-waste requirements, and DoD 5220.22-M procedures. Project details determine the appropriate records."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS serves Bakersfield and organizations throughout Kern County. Pickup planning can also support regional commercial projects when volume, access, equipment type, and scheduling requirements are reviewed in advance."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Many commercial projects can be scheduled within the same week after equipment details are confirmed. Timing depends on volume, loading conditions, access, route planning, and the documentation requested by your organization."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Available records can include pickup documentation, asset inventories, certificates of destruction, and downstream reporting. The specific record set depends on equipment type, project scope, and the customer's internal requirements."
          }
        },
        {
          "@type": "Question",
          "name": "What happens to equipment after pickup?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Equipment is received, evaluated, and routed through documented processing steps. Data-bearing devices receive the requested data handling, while recoverable materials move through responsible downstream recycling channels."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup free for Bakersfield organizations?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is available at no charge for qualifying volumes and projects. Contact STS with your equipment types, approximate quantity, access details, and preferred timing so the team can review the request."
          }
        },
        {
          "@type": "Question",
          "name": "How does Bakersfield electronics recycling work?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS Electronic Recycling coordinates scheduled pickup, serialized asset reporting, data handling, and downstream material recovery for Bakersfield businesses and organizations. Equipment is managed through a documented process based on the equipment type, project scope, and requested records."
          }
        },
        {
          "@type": "Question",
          "name": "What electronics can Bakersfield organizations recycle?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Commercial electronics recycling can include computers, laptops, mobile devices, networking equipment, printers, servers, monitors, copiers, and other technology collected during refresh cycles."
          }
        }
